function renderStats(){let weather=WEATHER[S.weather];document.getElementById('day-number').textContent=String(S.day).padStart(2,'0');document.getElementById('rail-day').textContent=`DÍA ${String(S.day).padStart(2,'0')}`;document.getElementById('weekday').textContent=WEEKDAYS[(S.day-1)%7];document.getElementById('time-label').textContent=`${String(Math.floor(S.time)).padStart(2,'0')}:${S.time%1? '30':'00'}`;document.getElementById('time-progress').style.width=`${Math.min(100,(S.time-6)/20*100)}%`;document.getElementById('energy-label').textContent=`${S.energy} / ${S.maxEnergy}`;document.getElementById('energy-bar').style.width=`${S.energy/S.maxEnergy*100}%`;document.getElementById('energy-hint').textContent=S.energy<20?'Te pesan los párpados. Ve con calma.':S.energy<50?'Guarda fuerzas para lo importante.':'Un día nuevo, todo por hacer.';document.getElementById('money').innerHTML=`${S.money} <small>₲</small>`;document.getElementById('weather-label').textContent=weather.label;document.getElementById('weather-icon').textContent=weather.icon;document.getElementById('weather-pill').innerHTML=`${weather.icon} <span>${weather.pill}</span><b>⌄</b>`;document.getElementById('fear-label').textContent=`${S.fear}%`;document.getElementById('fear-bar').style.width=`${S.fear}%`;document.getElementById('suspicion-label').textContent=`${S.suspicion}%`;document.getElementById('suspicion-bar').style.width=`${S.suspicion}%`;document.getElementById('mobile-date').textContent=`Día ${S.day} · Primavera`;document.getElementById('mobile-energy').textContent=`⚡ ${S.energy}`;document.getElementById('mobile-money').textContent=`✦ ${S.money}`;document.getElementById('daily-note').innerHTML=`<span class="note-pin">✦</span><p>${escapeHtml(S.lastNote)}</p><small>NOTA DEL DÍA</small>`;document.getElementById('town-count').textContent=`${Math.max(1,7-Math.floor(S.fear/22))} vecinos fuera`;document.getElementById('season-label').textContent='Primavera';document.getElementById('pages-count').textContent=Math.max(0,12-S.entries.length)}
function renderPlots(){const grid=document.getElementById('plot-grid');grid.innerHTML='';S.plots.forEach((p,i)=>{const crop=CROPS.find(c=>c.id===p.crop);const el=document.createElement('button');el.className=`plot ${!crop?'empty':''} ${p.watered?'watered':''} ${p.ready?'ready':''}`;let icon=crop?(p.ready?crop.icon:(p.progress>1?'🌱':'🌰')):'＋';let state=!crop?'Tierra vacía':p.ready?'Lista para cosechar':p.watered?`${crop.name} · creciendo`:`${crop.name} · necesita agua`;el.innerHTML=`<span class="plot-number">0${i+1}</span><span class="plot-crop">${icon}</span><span class="plot-state">${state}</span>${crop&&!p.ready?`<i class="plot-progress" style="width:${Math.min(100,p.progress/crop.days*100)}%"></i>`:''}`;el.onclick=()=>plotAction(i);grid.appendChild(el)})}
function renderInventory(){let node=document.getElementById('inventory-items');let items=Object.entries(S.inventory).filter(([,n])=>n>0);node.innerHTML=items.length?items.map(([id,n])=>{let c=CROPS.find(x=>x.id===id);return `<span class="inventory-item">${c?.icon||'✿'} ${n} ${c?.name||id}</span>`}).join(''):'<span class="inventory-item">Aún no hay cosecha</span>'}
function renderTown(){document.getElementById('place-list').innerHTML=PLACES.map(p=>`<button class="place-card" data-place="${p.id}"><span class="place-icon">${p.icon}</span><span><b>${p.name}</b><small>${placeDetail(p)}</small></span><span class="place-arrow">↗</span></button>`).join('');document.querySelectorAll('[data-place]').forEach(x=>x.onclick=()=>visitPlace(x.dataset.place));document.getElementById('town-quest').innerHTML=`<div class="quest-line"><span class="quest-check" style="${S.quests.turnip?'background:#e8f0e5;border-color:#94ad90':''}">${S.quests.turnip?'✓':''}</span><div><b>Una cesta para Mara</b><small>Entrega 2 nabos · ${S.quests.turnip?'Completado':'Recompensa: 40 ₲'}</small></div></div>`}
function placeDetail(p){if(p.id==='shop')return S.time<17?'Semillas y suministros':'Cerrado · vuelve mañana';if(p.id==='station')return S.time<19?'Luz está de turno':'Turno terminado';if(p.id==='tv')return S.time>=17&&S.time<21?'Noticias en directo':'Noticias · edición local';if(p.id==='shrine')return 'Entre los manzanos · quietud';return p.detail}
function renderNews(){document.getElementById('radio-news').textContent=S.news.length?S.news[S.news.length-1]:'La mañana trae el pronóstico, el precio de las hortalizas y una canción antigua. No hay sucesos de última hora.';document.getElementById('rail-rumor').innerHTML=`«${S.fear>50?'Las familias cierran temprano. Nadie quiere estar fuera después del anochecer.':S.entries.length?'En la plaza dicen que las ausencias no son casualidad.':'Alguien oyó pasos junto al santuario después de medianoche.'}»<small>— VECINA ANÓNIMA</small>`}
function renderNotebook(){const available=TARGETS.filter(t=>S.known.includes(t.id)&&!S.entries.some(e=>e.id===t.id));document.getElementById('known-target-count').textContent=`${S.known.length} / 5`;document.getElementById('entry-count').textContent=S.entries.length;document.getElementById('notebook-targets-label').textContent=`${available.length} disponibles`;document.getElementById('target-list').innerHTML=available.length?available.map(t=>`<div class="target-card ${S.selectedTarget===t.id?'selected':''}" data-target="${t.id}"><div class="target-avatar">${t.face?t.name[0]:'?'}<i class="face-dot"></i></div><div class="target-info"><b>${t.name}</b><small>${t.role}</small></div><span class="target-tag ${t.guilty?'proven':'unknown'}">${t.guilty?'Evidencia':'Duda'}</span></div>`).join(''):S.known.length?'<div class="empty-evidence">No hay nuevas entradas disponibles. La noche puede esperar.</div>':'<div class="empty-evidence">Los nombres aparecen al investigar en el pueblo.</div>';document.querySelectorAll('[data-target]').forEach(el=>el.onclick=()=>{S.selectedTarget=el.dataset.target;renderNotebook()});document.getElementById('write-btn').disabled=!S.selectedTarget||S.entries.length>=12;}
function renderBoard(){document.getElementById('evidence-count').textContent=`${S.evidence.length} pistas`;document.getElementById('evidence-list').innerHTML=S.evidence.length?S.evidence.map(e=>`<div class="evidence-card"><span class="evidence-icon">${e.icon||'⌕'}</span><div><b>${escapeHtml(e.title)}</b><p>${escapeHtml(e.text)}</p></div><span class="evidence-source">${escapeHtml(e.source||'OBSERVACIÓN')}</span></div>`).join(''):'<div class="empty-evidence">Todavía no hay pistas. Visita lugares y habla con los vecinos para comenzar.</div>';document.getElementById('hypothesis-count').textContent=Math.max(1,Math.floor(S.suspicion/18)+1);document.getElementById('detective-step').textContent=S.suspicion>65?'Vigilar tus rutinas':S.suspicion>35?'Contrastar horarios':'Observar';}
function renderPeople(){document.getElementById('relationship-grid').innerHTML=PEOPLE.map(p=>{let h=S.relationships[p.id]||0;let hearts=Math.floor(h/20);let status=S.entries.some(e=>e.id===p.id)?'Su ausencia pesa en el pueblo.':p.id==='sael'?'Te observa con cortesía.':h>35?'La confianza empieza a crecer.':'Una cara conocida en Valle Manzano.';return `<article class="person-card"><div class="person-portrait">${p.face}</div><div class="person-main"><b>${p.name}</b><small>${p.role}</small><div class="heart-row">${'♥'.repeat(Math.min(5,hearts))}<span class="empty-heart">${'♡'.repeat(5-Math.min(5,hearts))}</span></div></div><div class="person-actions"><button data-talk="${p.id}">Conversar · 1⚡</button><button data-gift="${p.id}">Dar regalo</button></div><div class="person-secret">${status}</div></article>`}).join('');document.querySelectorAll('[data-talk]').forEach(b=>b.onclick=()=>talk(b.dataset.talk));document.querySelectorAll('[data-gift]').forEach(b=>b.onclick=()=>gift(b.dataset.gift));let close=Object.values(S.relationships).filter(v=>v>=40).length;document.getElementById('friend-count').textContent=`${close} amistades cercanas`}
function addEvidence(title,text,source='OBSERVACIÓN',icon='⌕'){if(!S.evidence.some(e=>e.title===title)){S.evidence.push({title,text,source,icon});}}
function plotAction(i){if(S.energy<5){toast('Estás sin energía. Come algo o termina el día.');return}const p=S.plots[i];if(S.tool==='plant'||!S.tool){if(p.crop){toast('Esta parcela ya tiene algo creciendo.');return}openSeedPicker(i);return}if(S.tool==='water'){if(!p.crop){toast('Primero planta una semilla.');return}if(p.watered){toast('Ya regaste esta parcela hoy.');return}p.watered=true;spend(4,0.3);toast(`Regaste la parcela 0${i+1}.`)}else if(S.tool==='harvest'){if(!p.ready){toast(p.crop?'Todavía está creciendo.':'No hay nada que cosechar.');return}S.inventory[p.crop]=(S.inventory[p.crop]||0)+1;S.lastNote=`Cosechaste ${CROPS.find(c=>c.id===p.crop).name.toLowerCase()} en la parcela ${i+1}.`;S.plots[i]={crop:null,progress:0,watered:false,ready:false};spend(2,.2);toast('¡Cosecha guardada en la bolsa!')}render()}
function openSeedPicker(i){modal(`<div class="modal-kicker">PARCELA 0${i+1} · SEMILLAS</div><h2>¿Qué quieres sembrar?</h2><p>Cada cultivo tarda unos días en crecer. Riégalo cada jornada para avanzar. El tiempo es ficticio y pausado mientras lees.</p><div class="modal-seed-grid">${CROPS.map(c=>`<button class="seed-choice" onclick="plantCrop(${i},'${c.id}')"><span>${c.icon}</span><b>${c.name}</b><small>${c.days} días · ${c.cost} ₲</small></button>`).join('')}</div>`)}
function plantCrop(i,id){const c=CROPS.find(x=>x.id===id);if(S.money<c.cost){toast('No tienes suficiente dinero para esas semillas.');return}if(S.energy<4){toast('Te falta energía.');return}S.money-=c.cost;S.plots[i]={crop:id,progress:0,watered:false,ready:false};spend(4,.3);closeModal();toast(`Sembraste ${c.name.toLowerCase()}. ¡No olvides regar!`);render()}
function spend(energy,hours=1){S.energy=Math.max(0,S.energy-energy);S.time=Math.min(25,S.time+hours)}
function visitPlace(id){const p=PLACES.find(x=>x.id===id);if(['shop','station','tv'].includes(id)&&S.time>19){toast('Ya está cerrado por hoy.');return}if(S.energy<2){toast('Te falta energía para pasear.');return}spend(2,.7);S.visited[id]=(S.visited[id]||0)+1;if(id==='shop'){showShop();return}if(id==='tv'){S.known=[...new Set([...S.known,'dario'])];addEvidence('Edición de las seis','El Canal Valle informa que el concejal Castañeda enfrentará una auditoría. Su rostro y nombre aparecen juntos.','CANAL VALLE','▣');S.quests.clue=true;toast('Noticias de la tarde: una auditoría municipal. Nombre y rostro confirmados.');}else if(id==='station'){S.known=[...new Set([...S.known,'luz'])];addEvidence('Pizarra policial','Una nota de servicio menciona una filtración de datos. No hay culpable confirmado.','COMISARÍA','⌑');toast('Luz comparte un resumen público. La investigación continúa abierta.')}else if(id==='shrine'){S.known=[...new Set([...S.known,'basil'])];addEvidence('Huellas junto al santuario','Huellas de botas llegan al santuario y regresan al sendero. La lluvia borró el resto.','SANTUARIO','♧');toast('El silencio del santuario te devuelve una pista… y una mirada invisible.');S.stability=Math.max(0,S.stability-1)}else if(id==='forest'||id==='mine'){const item=id==='forest'?'Setas silvestres':'Piedra lisa';S.inventory[id]=(S.inventory[id]||0)+1;spend(3,.8);toast(`Encontraste: ${item}. Puedes entregarlo o venderlo.`);addEvidence('Un sendero poco transitado',id==='forest'?'Ramas quebradas marcan un camino que nadie menciona.':'La cantera guarda marcas de herramientas recientes.',id==='forest'?'BOSQUE':'CANTERA','♣')}else if(id==='cafe'){S.known=[...new Set([...S.known,'iris','nerea'])];addEvidence('Voces en el café','En la mesa vecina discuten una acusación viral contra Nerea; nadie presenta pruebas.','CAFÉ DEL PUENTE','☕');S.quests.clue=true;toast('Escuchaste un rumor. La mesa de al lado no sabe distinguir rumor de prueba.')}else if(id==='plaza'){if(S.day===7&&!S.flags.festival){festival();return}if(!S.quests.turnip)toast('Mara busca ayuda para preparar una cesta de bienvenida.');else toast('La plaza está tranquila. Darío te saluda desde los escalones.');S.relationships.mara=Math.min(100,S.relationships.mara+2)}render()}
function showShop(){modal(`<div class="modal-kicker">LA DESPENSA · ABIERTO HASTA LAS 17:00</div><h2>Semillas para la estación</h2><p>Saldo: <b>${S.money} ₲</b>. Los precios de venta son orientativos. No hay prisa: el tiempo se detiene aquí.</p><div class="shop-list">${CROPS.map(c=>`<div class="shop-row"><span>${c.icon}</span><div><b>Semillas de ${c.name.toLowerCase()}</b><small>${c.days} días · venta ${c.price} ₲</small></div><b>${c.cost} ₲</b><button onclick="buySeed('${c.id}')">Comprar</button></div>`).join('')}</div>`)}
function buySeed(id){const c=CROPS.find(x=>x.id===id);if(S.money<c.cost){toast('No alcanza el dinero.');return}S.money-=c.cost;S.inventory[`seed_${id}`]=(S.inventory[`seed_${id}`]||0)+1;toast(`Compraste semillas de ${c.name.toLowerCase()}. Planta desde tu parcela para usarlas.`);render();}
function sellHarvest(){let value=0,count=0;for(let [id,n] of Object.entries(S.inventory)){const c=CROPS.find(x=>x.id===id);if(c){value+=c.price*n;count+=n;delete S.inventory[id]}else if(id==='forest'){value+=14*n;count+=n;delete S.inventory[id]}else if(id==='mine'){value+=8*n;count+=n;delete S.inventory[id]}}if(!count){toast('La bolsa está vacía. Primero cosecha algo.');return}S.money+=value;S.lastNote=`Vendiste ${count} artículos por ${value} ₲ en el contenedor.`;render();toast(`Vendiste ${count} artículos por ${value} ₲.`)}
function talk(id){const p=PEOPLE.find(x=>x.id===id);if(S.energy<1){toast('No tienes energía para conversar.');return}spend(1,.35);S.relationships[id]=Math.min(100,(S.relationships[id]||0)+7);let line=p.lines[Math.floor(Math.random()*p.lines.length)];if(S.entries.length&&id==='sael')line=`«${S.suspicion>50?'He notado un patrón en tus horarios.':'Las ausencias pesan sobre todos.'} No es una acusación, por ahora.»`;if(id==='sael'){S.quests.sael=true;S.suspicion=Math.min(100,S.suspicion+1)}modal(`<div class="modal-kicker">VALLE MANZANO · CONVERSACIÓN</div><h2>${p.name}</h2><p><i>«${escapeHtml(line)}»</i></p><p>${S.relationships[id]>=40?'Se siente en confianza contigo.':'La conversación fue breve, pero sincera.'}</p><button class="primary-modal" onclick="closeModal()">Seguir con el día</button>`);render()}
function gift(id){if(S.energy<2){toast('Te falta energía para hacer una visita.');return}const items=Object.keys(S.inventory).filter(k=>S.inventory[k]>0);if(!items.length){toast('No tienes nada para regalar. Una cosecha o una seta servirían.');return}const item=items[0],c=CROPS.find(x=>x.id===item),name=c?.name||item;S.inventory[item]--;S.relationships[id]=Math.min(100,(S.relationships[id]||0)+(PEOPLE.find(p=>p.id===id).likes.toLowerCase().includes(name.toLowerCase())?18:9));spend(2,.4);toast(`Regalaste ${name} a ${PEOPLE.find(p=>p.id===id).name}. La confianza crece.`);render()}
function writeEntry(){let id=S.selectedTarget;if(!id)return;let t=TARGETS.find(x=>x.id===id);if(!t||!S.known.includes(id)){toast('Aún no tienes nombre y rostro confirmados.');return}if(S.entries.some(e=>e.id===id)){toast('Ya hay una entrada para esa persona.');return}const cause=document.getElementById('cause-select').value;if(S.energy<8){toast('Estás demasiado agotado para pensar con claridad.');return}const prevSusp=S.suspicion;S.entries.push({id,name:t.name,cause,day:S.day});S.fear=Math.min(100,S.fear+(t.guilty?12:24));S.suspicion=Math.min(100,S.suspicion+(t.guilty?12:19));S.devotion=Math.min(100,S.devotion+(t.guilty?10:17));S.community=Math.max(0,S.community-(t.guilty?5:15));S.justice=Math.max(0,S.justice+(t.guilty?8:-18));S.stability=Math.max(0,S.stability-(t.guilty?7:22));S.relationships[id]=0;S.energy-=8;let text=t.guilty?`Las noticias informan que ${t.name} no volverá a ocupar su cargo tras un suceso inexplicable. La auditoría continúa; la comunidad pide respuestas.`:`Una noticia breve comunica la ausencia de ${t.name}. Quienes la conocen rechazan las acusaciones sin pruebas. El pueblo está más asustado que antes.`;S.news.push(text);S.lastNote=`Anoche escribiste el nombre de ${t.name}. El pueblo despertó con preguntas.`;S.selectedTarget=null;S.time=Math.min(25,S.time+1);addEvidence('Una noticia sin explicación',`La ausencia de ${t.name} apareció en las noticias de la mañana. No hay un vínculo probado entre los hechos.`, 'NOTICIAS','▣');render();modal(`<div class="modal-kicker">LA NOCHE DEJÓ UNA HUELLA</div><h2>${t.guilty?'Un pueblo en silencio.':'Una acusación rota.'}</h2><p>${escapeHtml(text)}</p><p>${t.guilty?'La evidencia que tenías era sólida, pero el miedo no distingue matices.':'La pista era incompleta. Personas cercanas a la víctima han quedado marcadas por una decisión que no pueden comprender.'}</p><div class="ending-stats"><div><small>ATENCIÓN DEL DETECTIVE</small><b>${prevSusp}% → ${S.suspicion}%</b></div><div><small>INQUIETUD PÚBLICA</small><b>${S.fear}%</b></div></div><button class="primary-modal" onclick="closeModal()">Cerrar la página</button>`);}
function sleep(){if(S.flags.ending){showEnding(S.flags.ending);return}if(S.day>=28){finishSeason();return}let watered=0;S.plots.forEach(p=>{if(p.crop&&p.watered){let c=CROPS.find(x=>x.id===p.crop);p.progress++;watered++;if(p.progress>=c.days)p.ready=true}p.watered=false});S.day++;S.energy=S.maxEnergy;S.time=6;S.weather=(S.day*7+S.entries.length*3)%4;if(S.weather===1){S.plots.forEach(p=>{if(p.crop)p.watered=true})}if(S.day%7===0)S.weather=1;let headline='El pronóstico anuncia una jornada tranquila. La Despensa ofrece semillas de temporada.';if(S.entries.length){headline=S.news[S.news.length-1]}else if(S.day===2){headline='La radio informa de una auditoría en el ayuntamiento. El concejal Castañeda niega irregularidades.'}if(S.fear>55)headline='Varias tiendas cerrarán temprano. La comisaría pide evitar rumores y cuidar a los vecinos.';S.news.push(headline);S.lastNote=watered?`Regaste ${watered} parcelas antes de dormir. La cosecha avanza.`:'La lluvia nocturna regó el campo. Un día nuevo empieza.';if(S.suspicion>70){S.lastNote='Sael pidió a la comisaría que registre tus movimientos. No es una prueba; sí una advertencia.'}if(S.day===7&&!S.flags.festival){setTimeout(festival,200)}render();modal(`<div class="modal-kicker">NOTICIAS DE LA MAÑANA · DÍA ${String(S.day).padStart(2,'0')}</div><h2>${S.entries.length?'Una noticia que no se explica':'El valle despierta'}</h2><p>${escapeHtml(headline)}</p><p>${S.weather===1?'La lluvia empapó la tierra durante la noche. Las parcelas sembradas están regadas.':'El rocío cubre la plaza y las primeras tiendas levantan sus persianas.'}</p><button class="primary-modal" onclick="closeModal()">Empezar el día <span>→</span></button>`);}
function festival(){if(S.flags.festival)return;S.flags.festival=true;S.community=Math.min(100,S.community+4);S.relationships.mara=Math.min(100,S.relationships.mara+8);modal(`<div class="modal-kicker">DÍA 07 · PLAZA CENTRAL</div><div class="ending-hero">El mercado de primavera</div><p>Guirnaldas de papel cruzan la plaza. Mara vende mermelada, Iris entrevista a los artesanos y hasta Sael acepta una taza de té.</p><p>${S.fear>35?'La celebración es más pequeña este año. La gente se queda en grupos, mirando de reojo hacia la comisaría.':'Por unas horas, el pueblo consigue hablar de cosechas y del tiempo.'}</p><button class="primary-modal" onclick="closeModal()">Compartir la tarde <span>→</span></button>`);}
function finishSeason(){let ending;if(S.suspicion>=75)ending='discovered';else if(S.entries.length===0)ending='justice';else if(S.entries.length>=3&&S.fear>65)ending='kira';else ending='balance';showEnding(ending)}
function showEnding(ending){const info={kira:['El valle bajo una sola sombra','El miedo impuso silencio y las calles se vaciaron temprano. El pueblo parece ordenado desde lejos; de cerca, nadie confía en nadie. La granja prospera, pero las visitas dejaron de llegar.'],justice:['La paciencia también es justicia','Renunciaste a las páginas y ayudaste a Sael a separar los hechos de los rumores. La auditoría avanzó, la clínica siguió abierta y Valle Manzano aprendió a pedir pruebas antes de juzgar.'],balance:['Una primavera imperfecta','Elegiste con cautela, aunque ninguna decisión fue limpia. La comunidad conserva sus desacuerdos, pero aún comparte la mesa. Sael se marcha con preguntas y la granja vuelve a florecer.'],discovered:['La verdad sale a la luz','Las coincidencias se volvieron un patrón. Sael reunió horarios y testimonios, y una persona cercana encontró el cuaderno. La justicia tendrá que decidir qué hacer contigo; el pueblo tendrá que aprender a sanar.'],renounce:['Devolver lo imposible','Dejaste el cuaderno al pie del manzano más viejo. Bruma no discutió; solo pidió una última manzana. Por primera vez en semanas, dormiste sin esperar noticias al amanecer.']};S.flags.ending=ending;save();let [title,desc]=info[ending];modal(`<div class="modal-kicker">FINAL DE TEMPORADA · DÍA ${S.day}</div><div class="ending-hero">${title}</div><p>${desc}</p><div class="ending-stats"><div><small>PERSONAS AUSENTES</small><b>${S.entries.length} / 5</b></div><div><small>CONFIANZA DEL PUEBLO</small><b>${S.community}%</b></div><div><small>INQUIETUD</small><b>${S.fear}%</b></div><div><small>AMISTADES CERCANAS</small><b>${Object.values(S.relationships).filter(n=>n>=40).length}</b></div></div><p><b>Epílogo:</b> La granja terminó la estación con ${S.money} ₲. ${S.relationships.mara>=40?'Mara te visita los domingos.':'Mara deja una cesta en el porche.'} El valle seguirá hablando de esta primavera durante mucho tiempo.</p><button class="primary-modal" onclick="closeModal()">Cerrar el epílogo</button> <button class="secondary" onclick="newGame()">Empezar de nuevo</button>`);}
function newGame(){localStorage.removeItem('cuadernoCosechaSave');S=defaultState();closeModal();render();changeView('farm');toast('Una nueva primavera comienza.')}
function renounce(){closeModal();showEnding('renounce')}
function askBruma(){const lines=['«No puedo decirte quién es culpable. Las páginas no hacen esa distinción por ti.»','«La cámara capturó un rostro. No capturó la verdad.»','«Los humanos aman las respuestas simples. El bosque nunca las tuvo.»','«Una manzana por una pista. Es un trato justo, ¿no?»','«Sael cuenta tus pasos, no tus pensamientos. Eso ya es bastante.»'];document.getElementById('shinigami-line').textContent=lines[Math.floor(Math.random()*lines.length)];if(S.inventory.forest){S.inventory.forest--;S.known=[...new Set([...S.known,'iris'])];addEvidence('El silencio en la emisión','Iris dejó una pausa de tres segundos antes de leer el comunicado municipal. Puede ser nervios, no prueba.','BRUMA','◉');toast('Bruma acepta la seta como si fuera una manzana. Te da una pista ambigua.')}else toast('Bruma te mira con decepción. «Trae algo crujiente la próxima vez.»');render()}
function talkDetective(){S.relationships.sael=Math.min(100,S.relationships.sael+5);S.suspicion=Math.min(100,S.suspicion+1);S.quests.sael=true;addEvidence('Conversación con Sael','El detective confirma que contrasta horarios, pero no comparte una hipótesis sin evidencia.','COMISARÍA','◉');modal(`<div class="modal-kicker">COMISARÍA · CONVERSACIÓN</div><h2>Una pregunta, por ahora.</h2><p>Sael deja la taza sobre el mostrador. «Me interesa saber qué cambia después de cada noticia. La gente suele confundir el orden de los hechos.»</p><p>Te pregunta qué hacías durante la última emisión. Respondes con calma; toma nota, no acusa.</p><button class="primary-modal" onclick="closeModal()">Volver al tablón</button>`);render()}
function help(){modal(`<div class="modal-kicker">GUÍA RÁPIDA · 10 MINUTOS PARA EMPEZAR</div><h2>Una vida, dos ritmos.</h2><ul class="modal-list"><li><b>Granja:</b> selecciona Sembrar, Regar o Cosechar y pulsa una parcela. Cada acción cuesta energía.</li><li><b>Venta:</b> cosecha cultivos y véndelos desde la bolsa. Compra semillas en La Despensa.</li><li><b>Pueblo:</b> visita lugares para conocer a la gente y hallar pistas. El reloj corre; los menús se pausan.</li><li><b>Cuaderno:</b> la noticia o retrato debe confirmar identidad. Revisa pruebas antes de decidir.</li><li><b>Día siguiente:</b> termina la jornada con el botón de luna. La lluvia riega tus cultivos; al dormir recuperas energía.</li><li><b>Final:</b> renuncia al cuaderno desde el santuario o alcanza el día 28. También puedes pulsar ? para volver aquí.</li></ul><p>Tu partida se guarda automáticamente en este dispositivo.</p><button class="primary-modal" onclick="closeModal()">¡A jugar!</button>`)}
function calendar(){modal(`<div class="modal-kicker">CALENDARIO · AÑO 1</div><h2>Primavera</h2><p>28 días · 4 semanas · La tierra despierta.</p><div class="calendar-grid">${Array.from({length:28},(_,i)=>`<span class="${i+1===S.day?'today':''} ${[7,14,21,28].includes(i+1)?'event-day':''}"><small>${i+1}</small>${i+1===7?'✿':i+1===14?'☼':''}</span>`).join('')}</div><p>✿ Día 7 · Mercado de primavera &nbsp; ☼ Día 14 · Noche de faroles</p><button class="primary-modal" onclick="closeModal()">Cerrar calendario</button>`)}
function listenRadio(){if(!S.flags.radio){S.flags.radio=true;S.known=[...new Set([...S.known,'dario'])];addEvidence('Auditoría en el ayuntamiento','La radio local confirma que el consejo revisará fondos comunitarios. El concejal niega irregularidades.','RADIO VALLE','♫');S.quests.clue=true;S.relationships.iris=Math.min(100,S.relationships.iris+3);toast('La radio confirma un nombre y un rostro. Se inicia una auditoría.')}else toast('El boletín repite la petición de no difundir rumores.');render()}
function escapeHtml(str){return String(str).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function setup(){document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>changeView(b.dataset.view)));document.querySelectorAll('[data-tool]').forEach(b=>b.addEventListener('click',()=>{S.tool=b.dataset.tool;document.querySelectorAll('.tool').forEach(t=>t.classList.toggle('active',t===b));toast(`Herramienta: ${b.title.toLowerCase()}.`)}));document.getElementById('sleep-btn').onclick=sleep;document.getElementById('sell-btn').onclick=sellHarvest;document.getElementById('write-btn').onclick=writeEntry;document.getElementById('bruma-btn').onclick=askBruma;document.getElementById('help-btn').onclick=help;document.getElementById('calendar-btn').onclick=calendar;document.getElementById('calendar-small').onclick=calendar;document.getElementById('journal-btn').onclick=()=>modal(`<div class="modal-kicker">NOTA DEL DÍA ${S.day}</div><h2>Diario de campo</h2><p>${escapeHtml(S.lastNote)}</p><p>Dinero: ${S.money} ₲ · Energía: ${S.energy}/${S.maxEnergy} · Estabilidad: ${S.stability}%.</p><button class="primary-modal" onclick="closeModal()">Cerrar</button>`);document.getElementById('listen-radio').onclick=listenRadio;document.getElementById('detective-talk').onclick=talkDetective;document.getElementById('modal-close').onclick=closeModal;document.getElementById('modal-backdrop').onclick=e=>{if(e.target.id==='modal-backdrop')closeModal()};document.getElementById('sound-toggle').onclick=e=>{ambient=!ambient;e.currentTarget.textContent=ambient?'♫':'♪';toast(ambient?'Ambiente activado.':'Ambiente silenciado.');};document.getElementById('profile-btn').onclick=()=>modal(`<div class="modal-kicker">GRANJA MANZANO</div><h2>Tu historia, a tu ritmo.</h2><p>Una simulación narrativa sobre comunidad, responsabilidad y consecuencias. Todas las personas y sucesos son ficticios.</p><button class="primary-modal" onclick="renounce()">Devolver el cuaderno y terminar</button><button class="secondary" onclick="newGame()">Reiniciar partida</button>`);document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>changeView(b.dataset.go));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.target.tagName==='INPUT'||e.target.tagName==='SELECT')return;let map={'1':'farm','2':'town','3':'notebook','4':'board','5':'people'};if(map[e.key])changeView(map[e.key])});render();if(S.day===1&&!S.flags.intro)setTimeout(()=>modal(`<div class="modal-kicker">DÍA 01 · GRANJA MANZANO</div><div class="ending-hero">La llave todavía encaja.</div><p>La casa heredada huele a manzanas y madera mojada. Frente a ti: seis parcelas, una bolsa de semillas y un pueblo que parece conocerte de antes.</p><p>Empieza por sembrar y regar. Cuando quieras conocer Valle Manzano, visita la radio o pasea por la plaza. El día termina al elegir <b>Terminar el día</b>.</p><button class="primary-modal" onclick="closeModal()">Abrir la puerta</button>`),250)} }
setup();

