function visitPlace(id){const p=PLACES.find(x=>x.id===id);if(['shop','station','tv'].includes(id)&&S.time>19){toast('Ya está cerrado por hoy.');return}if(S.energy<2){toast('Te falta energía para pasear.');return}spend(2,.7);S.visited[id]=(S.visited[id]||0)+1;if(id==='shop'){showShop();return}if(id==='tv'){S.known=[...new Set([...S.known,'dario'])];addEvidence('Edición de las seis','El Canal Valle informa que el concejal Castañeda enfrentará una auditoría. Su rostro y nombre aparecen juntos.','CANAL VALLE','▣');S.quests.clue=true;toast('Noticias de la tarde: una auditoría municipal. Nombre y rostro confirmados.');}else if(id==='station'){S.known=[...new Set([...S.known,'luz'])];addEvidence('Pizarra policial','Una nota de servicio menciona una filtración de datos. No hay culpable confirmado.','COMISARÍA','⌑');toast('Luz comparte un resumen público. La investigación continúa abierta.')}else if(id==='shrine'){S.known=[...new Set([...S.known,'basil'])];addEvidence('Huellas junto al santuario','Huellas de botas llegan al santuario y regresan al sendero. La lluvia borró el resto.','SANTUARIO','♧');toast('El silencio del santuario te devuelve una pista… y una mirada invisible.');S.stability=Math.max(0,S.stability-1)}else if(id==='forest'||id==='mine'){const item=id==='forest'?'Setas silvestres':'Piedra lisa';S.inventory[id]=(S.inventory[id]||0)+1;spend(3,.8);toast(`Encontraste: ${item}. Puedes entregarlo o venderlo.`);addEvidence('Un sendero poco transitado',id==='forest'?'Ramas quebradas marcan un camino que nadie menciona.':'La cantera guarda marcas de herramientas recientes.',id==='forest'?'BOSQUE':'CANTERA','♣')}else if(id==='cafe'){S.known=[...new Set([...S.known,'iris','nerea'])];addEvidence('Voces en el café','En la mesa vecina discuten una acusación viral contra Nerea; nadie presenta pruebas.','CAFÉ DEL PUENTE','☕');S.quests.clue=true;toast('Escuchaste un rumor. La mesa de al lado no sabe distinguir rumor de prueba.')}else if(id==='plaza'){if(S.day===7&&!S.flags.fes