47: function renderStats(){let weather=WEATHER[S.weather];document.getElementById('day-number').textContent=String(S.day).padStart(2,'0');document.getElementById('rail-day').textContent=`DÍA ${String(S.day).padStart(2,'0')}`;document.getElementById('weekday').textContent=WEEKDAYS[(S.day-1)%7];document.getElementById('time-label').textContent=`${String(Math.floor(S.time)).padStart(2,'0')}:${S.time%1? '30':'00'}`;document.getElementById('time-progress').style.width=`${Math.min(100,(S.time-6)/20*100)}%`;document.getElementById('energy-label').textContent=`${S.energy} / ${S.maxEnergy}`;document.getElementById('energy-bar').style.width=`${S.energy/S.maxEnergy*100}%`;document.getElementById('energy-hint').textContent=S.energy<20?'Te pesan los párpados. Ve con calma.':S.energy<50?'Guarda fuerzas para lo importante.':'Un día nuevo, todo por hacer.';document.getElementById('money').innerHTML=`${S.money} <small>₲</small>`;document.getElementById('weather-label').textContent=weather.label;document.getElementById('weather-icon').textContent=weather.icon;document.getElementById('weather-pill').innerHTML=`${weather.icon} <span>${weather.pill}</span><b>⌄</b>`;document.getElementById('fear-label').textContent=`${S.fear}%`;document.getElementById('fear-bar').style.width=`${S.fear}%`;document.getElementById('suspicion-label').textContent=`${S.suspicion}%`;document.getElementById('suspicion-bar').style.width=`${S.suspicion}%`;document.getElementById('mobile-date').textContent=`Día ${S.day} · Primavera`;document.getElementById('mobile-energy').textContent=`⚡ ${S.energy}`;document.getElementById('mobile-money').textContent=`✦ ${S.money}`;document.getElementById('daily-note').innerHTML=`<span class="note-pin">✦</span><p>${escapeHtml(S.lastNote)}</p><small>NOTA DEL DÍA</small>`;document.getElementById('town-count').textContent=`${Math.max(1,7-Math.floor(S.fear/22))} vecinos fuera`;document.getElementById('season-label').textContent='Primavera';document.getElementById('pages-count').textConten... (line truncated to 2000 chars)
48: function renderPlots(){const grid=document.getElementById('plot-grid');grid.innerHTML='';S.plots.forEach((p,i)=>{const crop=CROPS.find(c=>c.id===p.crop);const el=document.createElement('button');el.className=`plot ${!crop?'empty':''} ${p.watered?'watered':''} ${p.ready?'ready':''}`;let icon=crop?(p.ready?crop.icon:(p.progress>1?'🌱':'🌰')):'＋';let state=!crop?'Tierra vacía':p.ready?'Lista para cosechar':p.watered?`${crop.name} · creciendo`:`${crop.name} · necesita agua`;el.innerHTML=`<span class="plot-number">0${i+1}</span><span class="plot-crop">${icon}</span><span class="plot-state">${state}</span>${crop&&!p.ready?`<i class="plot-progress" style="width:${Math.min(100,p.progress/crop.days*100)}%"></i>`:''}`;el.onclick=()=>plotAction(i);grid.appendChild(el)})}
49: function renderInventory(){let node=document.getElementById('inventory-items');let items=Object.entries(S.inventory).filter(([,n])=>n>0);node.innerHTML=items.length?items.map(([id,n])=>{let c=CROPS.find(x=>x.id===id);return `<span class="inventory-item">${c?.icon||'✿'} ${n} ${c?.name||id}</span>`}).join(''):'<span class="inventory-item">Aún no hay cosecha</span>'}
50: function renderTown(){document.getElementById('place-list').innerHTML=PLACES.map(p=>`<button class="place-card" data-place="${p.id}"><span class="place-icon">${p.icon}</span><span><b>${p.name}</b><small>${placeDetail(p)}</small></span><span class="place-arrow">↗</span></button>`).join('');document.querySelectorAll('[data-place]').forEach(x=>x.onclick=()=>visitPlace(x.dataset.place));document.getElementById('town-quest').innerHTML=`<div class="quest-line"><span class="quest-check" style="${S.quests.turnip?'background:#e8f0e5;border-color:#94ad90':''}">${S.quests.turnip?'✓':''}</span><div><b>Una cesta para Mara</b><small>Entrega 2 nabos · ${S.quests.turnip?'Completado':'Recompensa: 40 ₲'}</small></div></div>`}
51: function placeDetail(p){if(p.id==='shop')return S.time<17?'Semillas y suministros':'Cerrado · vuelve mañana';if(p.id==='station')return S.time<19?'Luz está de turno':'Turno terminado';if(p.id==='tv')return S.time>=17&&S.time<21?'Noticias en directo':'Noticias · edición local';if(p.id==='shrine')return 'Entre los manzanos · quietud';return p.detail}
52: function renderNews(){document.getElementById('radio-news').textContent=S.news.length?S.news[S.news.length-1]:'La mañana trae el pronóstico, el precio de las hortalizas y una canción antigua. No hay sucesos de última hora.';document.getElementById('rail-rumor').innerHTML=`«${S.fear>50?'Las familias cierran temprano. Nadie quiere estar fuera después del anochecer.':S.entries.length?'En la plaza dicen que las ausencias no son casualidad.':'Alguien oyó pasos junto al santuario después de medianoche.'}»<small>— VECINA ANÓNIMA</small>`}
