### visitPlace
function visitPlace(id){const p=PLACES.find(x=>x.id===id);
if(['shop','station','tv'].includes(id)&&S.time>19){toast('Ya está cerrado por hoy.');
return}if(S.energy<2){toast('Te falta energía para pasear.');
return}spend(2,.7);
S.visited[id]=(S.visited[id]||0)+1;
if(id==='shop'){showShop();
return}if(id==='tv'){S.known=[...new Set([...S.known,'dario'])];
addEvidence('Edición de las seis','El Canal Valle informa que el concejal Castañeda enfrentará una auditoría. Su rostro y nombre aparecen juntos.','CANAL VALLE','▣');
S.quests.clue=true;
toast('Noticias de la tarde: una auditoría municipal. Nombre y rostro confirmados.');
}else if(id==='station'){S.known=[...new Set([...S.known,'luz'])];
addEvidence('Pizarra policial','Una nota de servicio menciona una filtración de datos. No hay culpable confirmado.','COMISARÍA','⌑');
toast('Luz comparte un resumen público. La investigación continúa abierta.')}else if(id==='shrine'){S.known=[...new Set([...S.known,'basil'])];
addEvidence('Huellas junto al santuario','Huellas de botas llegan al santuario y regresan al sendero. La lluvia borró el resto.','SANTUARIO','♧');
toast('El silencio del santuario te devuelve una pista… y una mirada invisible.');
S.stability=Math.max(0,S.stability-1)}else if(id==='forest'||id==='mine'){const item=id==='forest'?'Setas silvestres':'Piedra lisa';
S.inventory[id]=(S.inventory[id]||0)+1;
spend(3,.8);
toast(`Encontraste: ${item}. Puedes entregarlo o venderlo.`);
addEvidence('Un sendero poco transitado',id==='forest'?'Ramas quebradas marcan un camino que nadie menciona.':'La cantera guarda marcas de herramientas recientes.',id==='forest'?'BOSQUE':'CANTERA','♣')}else if(id==='cafe'){S.known=[...new Set([...S.known,'iris','nerea'])];
addEvidence('Voces en el café','En la mesa vecina discuten una acusación viral contra Nerea;
 nadie presenta pruebas.','CAFÉ DEL PUENTE','☕');
S.quests.clue=true;
toast('Escuchaste un rumor. La mesa de al lado no sabe distinguir rumor de prueba.')}else if(id==='plaza'){if(S.day===7&&!S.flags.festival){festival();
return}if(!S.quests.turnip)toast('Mara busca ayuda para preparar una cesta de bienvenida.');
else toast('La plaza está tranquila. Darío te saluda desde los escalones.');
S.relationships.mara=Math.min(100,S.relationships.mara+2)}render()}

### festival
function festival(){if(S.flags.festival)return;
S.flags.festival=true;
S.community=Math.min(100,S.community+4);
S.relationships.mara=Math.min(100,S.relationships.mara+8);
modal(`<div class="modal-kicker">DÍA 07 · PLAZA CENTRAL</div><div class="ending-hero">El mercado de primavera</div><p>Guirnaldas de papel cruzan la plaza. Mara vende mermelada, Iris entrevista a los artesanos y hasta Sael acepta una taza de té.</p><p>${S.fear>35?'La celebración es más pequeña este año. La gente se queda en grupos, mirando de reojo hacia la comisaría.':'Por unas horas, el pueblo consigue hablar de cosechas y del tiempo.'}</p><button class="primary-modal" onclick="closeModal()">Compartir la tarde <span>→</span></button>`);
}

### showEnding
function showEnding(ending){const info={kira:['El valle bajo una sola sombra','El miedo impuso silencio y las calles se vaciaron temprano. El pueblo parece ordenado desde lejos;
 de cerca, nadie confía en nadie. La granja prospera, pero las visitas dejaron de llegar.'],justice:['La paciencia también es justicia','Renunciaste a las páginas y ayudaste a Sael a separar los hechos de los rumores. La auditoría avanzó, la clínica siguió abierta y Valle Manzano aprendió a pedir pruebas antes de juzgar.'],balance:['Una primavera imperfecta','Elegiste con cautela, aunque ninguna decisión fue limpia. La comunidad conserva sus desacuerdos, pero aún comparte la mesa. Sael se marcha con preguntas y la granja vuelve a florecer.'],discovered:['La verdad sale a la luz','Las coincidencias se volvieron un patrón. Sael reunió horarios y testimonios, y una persona cercana encontró el cuaderno. La justicia tendrá que decidir qué hacer contigo;
 el pueblo tendrá que aprender a sanar.'],renounce:['Devolver lo imposible','Dejaste el cuaderno al pie del manzano más viejo. Bruma no discutió;
 solo pidió una última manzana. Por primera vez en semanas, dormiste sin esperar noticias al amanecer.']};
S.flags.ending=ending;
