function lanternFestival(){if(S.flags.lanterns)return;S.flags.lanterns=true;render();modal(`<div class="modal-kicker">DÍA 14 · PLAZA CENTRAL · ANOCHECER</div><div class="ending-hero">La noche de los faroles</div><p>Elia ha colgado faroles de papel entre los manzanos. Cada uno lleva un deseo anónimo para el valle. Sael observa desde el borde de la plaza, sin interrumpir.</p><p>${S.fear>45?'Hay faroles sin encender. Algunas familias se marcharon antes del anochecer.':'La luz cálida reúne a vecinos que no suelen quedarse hablando.'} ¿Cómo quieres acompañar la noche?</p><div class="festival-choices"><button class="secondary" onclick="lanternChoice('help')">Ayudar a Elia a encenderlos · 4⚡</button><button class="secondary" onclick="lanternChoice('sael')">Escuchar la reflexión de Sael</button><button class="secondary" onclick="lanternChoice('quiet')">Compartir un momento en silencio</button></div>`);}
function lanternChoice(choice){if(choice==='help'){if(S.energy<4){toast('Te falta energía para ayudar a encender los faroles. Elige otra forma de acompañar la noche.');return}spend(4,.3);S.relationships.elia=Math.min(100,S.relationships.elia+12);S.relationships.mara=Math.min(100,S.relationships.mara+3);S.community=Math.min(100,S.community+5);S.fear=Math.max(0,S.fear-3);S.lastNote='Ayudaste a Elia a encender los faroles. Por un rato, la plaza volvió a sentirse como un hogar.';addEvidence('Deseos bajo la luz','Elia cuenta que los faroles son una tradición para recordar lo que el vecindario quiere proteger. No contienen nombres ni acusaciones.','FESTIVAL DE FAROLES','☼');closeModal();toast('Elia agradece tu ayuda. La plaza se siente un poco más unida.')}else if(choice==='sael'){S.relationships.sael=Math.min(100,S.relationships.sael+6);S.relationships.elia=Math.min(100,S.relationships.elia+3);S.community=Math.min(100,S.community+2);S.quests.sael=true;addEvidence('Una conversación en la plaza','Sael recuerda que un horario puede orientar una investigación, pero nunca sustituye una prueba.','FESTIVAL DE FAROLES','◉');S.lastNote='Sael habló de paciencia bajo los faroles: observar no es lo mismo que acusar.';closeModal();toast('Sael compartió una reflexión, no una sospecha.')}else{S.stability=Math.min(100,S.stability+4);S.fear=Math.max(0,S.fear-2);S.relationships.elia=Math.min(100,S.relationships.elia+5);S.community=Math.min(100,S.community+3);S.lastNote='Compartiste en silencio la noche de faroles. No todas las respuestas necesitan una página.';closeModal();toast('Elia te acompaña en silencio. La noche se vuelve más serena.')}render();}

