function visitPlace(id){const p=PLACES.find(x=>x.id===id);if((id==='shop'&&S.time>=17)||(id==='station'&&S.time>=19)||(id==='tv'&&S.time>=21)){toast('Ya está cerrado por hoy.');return}if(S.energy<2){toast('Te falta energía para pasear.');return}spend(2,.7);S.visited[id]=(S.visited[id]||0)+1;if(id==='shop'){render();showShop();return}if(id==='tv'){S.known=[...new Set([...S.known,'dario'])];addEvidence('Edición de las seis','El Canal Valle informa que el concejal Castañeda enfrentará una auditoría. Su rostro y nombre aparecen juntos.','CANAL VALLE','▣');S.quests.clue=true;toast('Noticias de la tarde: una auditoría municipal. Nombre y rostro confirmados.');}else if(id==='station'){S.known=[...new Set([...S.known,'luz'])];addEvidence('Pizarra policial','Una nota de servicio menciona una filtración de datos. No hay culpable confirmado.','COMISARÍA','⌑');toast('Luz comparte un resumen público. La investigación continúa abierta.')}else if(id==='shrine'){S.known=[...new Set([...S.known,'basil'])];addEvidence('Huellas junto al santuario','Huellas de botas llegan al santuario y regresan al sendero. La lluvia borró el resto.','SANTUARIO','♧');toast('El silencio del santuario te devuelve una pista… y una mirada invisible.');S.stability=Math.max(0,S.stability-1)}else if(id==='forest'||id==='mine'){const item=id==='forest'?'Setas silvestres':'Piedra lisa';S.inventory[id]=(S.inventory[id]||0)+1;spend(3,.8);toast(`Encontraste: ${item}. Puedes entregarlo o venderlo.`);addEvidence('Un sendero poco transitado',id==='forest'?'Ramas quebradas marcan un camino que nadie menciona.':'La cantera guarda marcas de herramientas recientes.',id==='forest'?'BOSQUE':'CANTERA','♣')}else if(id==='cafe'){S.known=[...new Set([...S.known,'iris','nerea'])];addEvidence('Voces en el café','En la mesa vecina discuten una acusación viral contra Nerea; nadie presenta pruebas.','CAFÉ DEL PUENTE','☕');S.quests.clue=true;toast('Escuchaste un rumor. La mesa de al lado no sabe distinguir rumor de prueba.')}else if(id==='plaza'){if(S.day===7&&!S.flags.festival){festival();return}if(S.day===14&&S.time>=19&&!S.flags.lanterns){lanternFestival();return}if(!S.quests.turnip)toast('Mara busca ayuda para preparar una cesta de bienvenida.');else toast('La plaza está tranquila. Darío te saluda desde los escalones.');S.relationships.mara=Math.min(100,S.relationships.mara+2)}render()}
function showShop(){modal(`<div class="modal-kicker">LA DESPENSA · ABIERTO HASTA LAS 17:00</div><h2>Semillas para la estación</h2><p>Saldo: <b>${S.money} ₲</b>. Los precios de venta son orientativos. No hay prisa: el tiempo se detiene aquí.</p><div class="shop-list">${CROPS.map(c=>`<div class="shop-row"><span>${c.icon}</span><div><b>Semillas de ${c.name.toLowerCase()}</b><small>${c.days} días · venta ${c.price} ₲</small></div><b>${c.cost} ₲</b><button onclick="buySeed('${c.id}')">Comprar</button></div>`).join('')}</div>`)}
function buySeed(id){const c=CROPS.find(x=>x.id===id);if(S.money<c.cost){toast('No alcanza el dinero.');return}S.money-=c.cost;S.inventory[`seed_${id}`]=(S.inventory[`seed_${id}`]||0)+1;toast(`Compraste semillas de ${c.name.toLowerCase()}. Planta desde tu parcela para usarlas.`);render();}
function sellHarvest(){let value=0,count=0;for(let [id,n] of Object.entries(S.inventory)){const c=CROPS.find(x=>x.id===id);if(c&&n>0){value+=c.price*n;count+=n;delete S.inventory[id]}else if(id==='forest'&&n>0){value+=14*n;count+=n;delete S.inventory[id]}else if(id==='mine'&&n>0){value+=8*n;count+=n;delete S.inventory[id]}}if(!count){toast('No tienes cosechas ni objetos vendibles.');return}S.money+=value;S.lastNote=`Vendiste ${count} artículos por ${value} ₲ en el contenedor.`;render();toast(`Vendiste ${count} artículos por ${value} ₲.`)}
function talk(id){const p=PEOPLE.find(x=>x.id===id);if(S.energy<1){toast('No tienes energía para conversar.');return}spend(1,.35);S.relationships[id]=Math.min(100,(S.relationships[id]||0)+7);let line=p.lines[Math.floor(Math.random()*p.lines.length)];if(S.entries.length&&id==='sael')line=`«${S.suspicion>50?'He notado un patrón en tus horarios.':'Las ausencias pesan sobre todos.'} No es una acusación, por ahora.»`;if(id==='sael'){S.quests.sael=true;S.suspicion=Math.min(100,S.suspicion+1)}modal(`<div class="modal-kicker">VALLE MANZANO · CONVERSACIÓN</div><h2>${p.name}</h2><p><i>«${escapeHtml(line)}»</i></p><p>${S.relationships[id]>=40?'Se siente en confianza contigo.':'La conversación fue breve, pero sincera.'}</p><button class="primary-modal" onclick="closeModal()">Seguir con el día</button>`);render()}
function gift(id,itemKey){if(S.energy<2){toast('Te falta energía para hacer una visita.');return}const items=Object.keys(S.inventory).filter(k=>S.inventory[k]>0&&!k.startsWith('seed_'));if(!items.length){toast('No tienes objetos para regalar. Las semillas no se pueden regalar.');return}const person=PEOPLE.find(p=>p.id===id);if(!itemKey){modal(`<div class="modal-kicker">UN DETALLE PARA ${escapeHtml(person.name.toUpperCase())}</div><h2>¿Qué quieres regalar?</h2><div class="shop-list">${items.map(k=>{const c=CROPS.find(x=>x.id===k),name=c?.name||(k==='forest'?'Setas silvestres':k==='mine'?'Piedra lisa':k);return `<div class="shop-row"><span>${c?.icon||'✿'}</span><div><b>${escapeHtml(name)}</b><small>En la bolsa: ${S.inventory[k]}</small></div><button onclick="gift('${id}','${k}')">Elegir</button></div>`}).join('')}</div>`);return}if(!items.includes(itemKey)){toast('Ese objeto ya no está en la bolsa.');return}const c=CROPS.find(x=>x.id===itemKey),name=c?.name||(itemKey==='forest'?'Setas silvestres':itemKey==='mine'?'Piedra lisa':itemKey);S.inventory[itemKey]--;if(!S.inventory[itemKey])delete S.inventory[itemKey];const liked=person.likes.toLowerCase().includes(name.toLowerCase());S.relationships[id]=Math.min(100,(S.relationships[id]||0)+(liked?18:9));spend(2,.4);closeModal();toast(`Regalaste ${name} a ${person.name}. ${liked?'Era justo lo que le gusta.':'La confianza crece.'}`);render()}
function writeEntry(){let id=S.selectedTarget;if(!id)return;let t=TARGETS.find(x=>x.id===id);if(!t||!S.known.includes(id)){toast('Aún no tienes nombre y rostro confirmados.');return}if(S.entries.some(e=>e.id===id)){toast('Ya hay una entrada para esa persona.');return}const cause=document.getElementById('cause-select').value;if(S.energy<8){toast('Estás demasiado agotado para pensar con claridad.');return}const prevSusp=S.suspicion;S.entries.push({id,name:t.name,cause,day:S.day});S.fear=Math.min(100,S.fear+(t.guilty?12:24));S.suspicion=Math.min(100,S.suspicion+(t.guilty?12:19));S.devotion=Math.min(100,S.devotion+(t.guilty?10:17));S.community=Math.max(0,S.community-(t.guilty?5:15));S.justice=Math.max(0,S.justice+(t.guilty?8:-18));S.stability=Math.max(0,S.stability-(t.guilty?7:22));S.relationships[id]=0;S.energy-=8;let text=t.guilty?`Las noticias informan que ${t.name} no volverá a ocupar su cargo tras un suceso inexplicable. La auditoría continúa; la comunidad pide respuestas.`:`Una noticia breve comunica la ausencia de ${t.name}. Quienes la conocen rechazan las acusaciones sin pruebas. El pueblo está más asustado que antes.`;S.news.push(text);S.lastNote=`Anoche escribiste el nombre de ${t.name}. El pueblo despertó con preguntas.`;S.selectedTarget=null;S.time=Math.min(25,S.time+1);addEvidence('Una noticia sin explicación',`La ausencia de ${t.name} apareció en las noticias de la mañana. No hay un vínculo probado entre los hechos.`, 'NOTICIAS','▣');render();modal(`<div class="modal-kicker">LA NOCHE DEJÓ UNA HUELLA</div><h2>${t.guilty?'Un pueblo en silencio.':'Una acusación rota.'}</h2><p>${escapeHtml(text)}</p><p>${t.guilty?'La evidencia que tenías era sólida, pero el miedo no distingue matices.':'La pista era incompleta. Personas cercanas a la víctima han quedado marcadas por una decisión que no pueden comprender.'}</p><div class="ending-stats"><div><small>ATENCIÓN DEL DETECTIVE</small><b>${prevSusp}% → ${S.suspicion}%</b></div><div><small>INQUIETUD PÚBLICA</small><b>${S.fear}%</b></div></div><button class="primary-modal" onclick="closeModal()">Cerrar la página</button>`);}
function sleep(){if(S.flags.ending){showEnding(S.flags.ending);return}if(S.day>=28){finishSeason();return}let watered=0;S.plots.forEach(p=>{if(p.crop&&p.watered){let c=CROPS.find(x=>x.id===p.crop);p.progress++;watered++;if(p.progress>=c.days)p.ready=true}p.watered=false});S.day++;S.energy=S.maxEnergy;S.time=6;S.weather=(S.day*7+S.entries.length*3)%4;if(S.weather===1){S.plots.forEach(p=>{if(p.crop)p.watered=true})}if(S.day%7===0)S.weather=1;let headline='El pronóstico anuncia una jornada tranquila. La Despensa ofrece semillas de temporada.';if(S.entries.length){headline=S.news[S.news.length-1]}else if(S.day===2){headline='La radio informa de una auditoría en el ayuntamiento. El concejal Castañeda niega irregularidades.'}if(S.fear>55)headline='Varias tiendas cerrarán temprano. La comisaría pide evitar rumores y cuidar a los vecinos.';S.news.push(headline);S.lastNote=watered?`Regaste ${watered} parcelas antes de dormir. La cosecha avanza.`:'La lluvia nocturna regó el campo. Un día nuevo empieza.';if(S.suspicion>70){S.lastNote='Sael pidió a la comisaría que registre tus movimientos. No es una prueba; sí una advertencia.'}render();modal(`<div class="modal-kicker">NOTICIAS DE LA MAÑANA · DÍA ${String(S.day).padStart(2,'0')}</div><h2>${S.entries.length?'Una noticia que no se explica':'El valle despierta'}</h2><p>${escapeHtml(headline)}</p><p>${S.weather===1?'La lluvia empapó la tierra durante la noche. Las parcelas sembradas están regadas.':'El rocío cubre la plaza y las primeras tiendas levantan sus persianas.'}</p><button class="primary-modal" onclick="closeModal()">Empezar el día <span>→</span></button>`);}
function festival(){if(S.flags.festival)return;S.flags.festival=true;S.community=Math.min(100,S.community+4);S.relationships.mara=Math.min(100,S.relationships.mara+8);render();modal(`<div class="modal-kicker">DÍA 07 · PLAZA CENTRAL</div><div class="ending-hero">El mercado de primavera</div><p>Guirnaldas de papel cruzan la plaza. Mara vende mermelada, Iris entrevista a los artesanos y hasta Sael acepta una taza de té.</p><p>${S.fear>35?'La celebración es más pequeña este año. La gente se queda en grupos, mirando de reojo hacia la comisaría.':'Por unas horas, el pueblo consigue hablar de cosechas y del tiempo.'}</p><button class="primary-modal" onclick="closeModal()">Compartir la tarde <span>→</span></button>`);}
function lanternFestival(){if(S.flags.lanterns)return;S.flags.lanterns=true;render();modal(`<div class="modal-kicker">DÍA 14 · PLAZA CENTRAL · ANOCHECER</div><div class="ending-hero">La noche de los faroles</div><p>Elia ha colgado faroles de papel entre los manzanos. Cada uno lleva un deseo anónimo para el valle. Sael observa desde el borde de la plaza, sin interrumpir.</p><p>${S.fear>45?'Hay faroles sin encender. Algunas familias se marcharon antes del anochecer.':'La luz cálida reúne a vecinos que no suelen quedarse hablando.'} ¿Cómo quieres acompañar la noche?</p><div class="festival-choices"><button class="secondary" onclick="lanternChoice('help')">Ayudar a Elia a encenderlos · 4⚡</button><button class="secondary" onclick="lanternChoice('sael')">Escuchar la reflexión de Sael</button><button class="secondary" onclick="lanternChoice('quiet')">Compartir un momento en silencio</button></div>`);}
function lanternChoice(choice){if(choice==='help'){if(S.energy<4){toast('Te falta energía para ayudar a encender los faroles. Elige otra forma de acompañar la noche.');return}spend(4,.3);S.relationships.elia=Math.min(100,S.relationships.elia+12);S.relationships.mara=Math.min(100,S.relationships.mara+3);S.community=Math.min(100,S.community+5);S.fear=Math.max(0,S.fear-3);S.lastNote='Ayudaste a Elia a encender los faroles. Por un rato, la plaza volvió a sentirse como un hogar.';addEvidence('Deseos bajo la luz','Elia cuenta que los faroles son una tradición para recordar lo que el vecindario quiere proteger. No contienen nombres ni acusaciones.','FESTIVAL DE FAROLES','☼');closeModal();toast('Elia agradece tu ayuda. La plaza se siente un poco más unida.')}else if(choice==='sael'){S.relationships.sael=Math.min(100,S.relationships.sael+6);S.relationships.elia=Math.min(100,S.relationships.elia+3);S.community=Math.min(100,S.community+2);S.quests.sael=true;addEvidence('Una conversación en la plaza','Sael recuerda que un horario puede orientar una investigación, pero nunca sustituye una prueba.','FESTIVAL DE FAROLES','◉');S.lastNote='Sael habló de paciencia bajo los faroles: observar no es lo mismo que acusar.';closeModal();toast('Sael compartió una reflexión, no una sospecha.')}else{S.stability=Math.min(100,S.stability+4);S.fear=Math.max(0,S.fear-2);S.relationships.elia=Math.min(100,S.relationships.elia+5);S.community=Math.min(100,S.community+3);S.lastNote='Compartiste en silencio la noche de faroles. No todas las respuestas necesitan una página.';closeModal();toast('Elia te acompaña en silencio. La noche se vuelve más serena.')}render();}
function finishSeason(){let ending;if(S.suspicion>=75)ending='discovered';else if(S.entries.length===0)ending='justice';else if(S.entries.length>=3&&S.fear>65)ending='kira';else ending='balance';showEnding(ending)}
function showEnding(ending){const info={kira:['El valle bajo una sola sombra','El miedo impuso silencio y las calles se vaciaron temprano. El pueblo parece ordenado desde lejos; de cerca, nadie confía en nadie. La granja prospera, pero las visitas dejaron de llegar.'],justice:['La paciencia también es justicia','Renunciaste a las páginas y ayudaste a Sael a separar los hechos de los rumores. La auditoría avanzó, la clínica siguió abierta y Valle Manzano aprendió a pedir pruebas antes de juzgar.'],balance:['Una primavera imperfecta','Elegiste con cautela, aunque ninguna decisión fue limpia. La comunidad conserva sus desacuerdos, pero aún comparte la mesa. Sael se marcha con preguntas y la granja vuelve a florecer.'],discovered:['La verdad sale a la luz','Las coincidencias se volvieron un patrón. Sael reunió horarios y testimonios, y una persona cercana encontró el cuaderno. La justicia tendrá que decidir qué hacer contigo; el pueblo tendrá que aprender a sanar.'],renounce:['Devolver lo imposible','Dejaste el cuaderno al pie del manzano más viejo. Bruma no discutió; solo pidió una última manzana. Por primera vez en semanas, dormiste sin esperar noticias al amanecer.']};S.flags.ending=ending;save();let [title,desc]=info[ending];modal(`<div class="modal-kicker">FINAL DE TEMPORADA · DÍA ${S.day}</div><div class="ending-hero">${title}</div><p>${desc}</p><div class="ending-stats"><div><small>PERSONAS AUSENTES</small><b>${S.entries.length} / 5</b></div><div><small>CONFIANZA DEL PUEBLO</small><b>${S.community}%</b></div><div><small>INQUIETUD</small><b>${S.fear}%</b></div><div><small>AMISTADES CERCANAS</small><b>${Object.values(S.relationships).filter(n=>n>=40).length}</b></div></div><p><b>Epílogo:</b> La granja terminó la estación con ${S.money} ₲. ${S.relationships.mara>=40?'Mara te visita los domingos.':'Mara deja una cesta en el porche.'} El valle seguirá hablando de esta primavera durante mucho tiempo.</p><button class="primary-modal" onclick="closeModal()">Cerrar el epílogo</button> <button class="secondary" onclick="newGame()">Empezar de nuevo</button>`);}
